&\implies(2x+y-2)\overrightarrow{AF}+(2x-3y)\overrightarrow{FE}=0
\implies\{2x+y-2=0,2x-3y=0\}
\implies(x,y)=\left(\frac{3}{4},\frac{1}{2}\right)
\end{align*}

